select energy_manager.load_cards($cards$[
{"id":"p3-b07-025","paper":3,"topic":"Cooling Tower","kind":"fact","front":"Name the main factors that promote corrosion in cooling water systems.","back":"High salinity, low pH, low alkalinity, corrosive gases (mainly oxygen and CO₂), and dissimilar metals.","explain":"Corrosion is not precisely understood, but these factors are the main drivers. It can cause heat exchanger leaks and deposits of corrosion products.","flash":false,"source":"BEE Book 3 Ch 07 p243","order":3367},
{"id":"p3-b07-026","paper":3,"topic":"Cooling Tower","kind":"fact","front":"When does an open condenser water circuit on softened water face severe scaling?","back":"When the pH of the circulating water is above 9.0, total alkalinity (as CaCO₃) is above 550 ppm, or temporary hardness of the make-up is above 200 ppm.","explain":"High calcium and magnesium levels, together with high pH and alkalinity, are the main sources of scale in open evaporative condenser circuits.","flash":false,"source":"BEE Book 3 Ch 07 p243","order":3368},
{"id":"p3-b07-027","paper":3,"topic":"Cooling Tower","kind":"fact","front":"What does a side stream filter handle, and how often should the total system water be filtered?","back":"A side stream filter handles 2% to 5% of the total circulation rate, sized so that the total system water (hold-up volume) is filtered about once every 12 hours.","explain":"Side stream filters are needed where circulating water has very high turbidity or suspended impurities.","flash":false,"source":"BEE Book 3 Ch 07 p244","order":3369},
{"id":"p3-b07-028","paper":3,"topic":"Cooling Tower","kind":"fact","front":"Which oxidising biocide is the most effective and most economical, and what do bio-dispersants do?","back":"Chlorination. Bio-dispersants remove the upper layer of biological masses so that biocides can penetrate the lower layers.","explain":"For volumes above 100 m³, suitable gas chlorinators are used. The safest are vacuum gravity feed types, installed on 50 kg or 100 kg chlorine cylinders.","flash":false,"source":"BEE Book 3 Ch 07 p245","order":3370},
{"id":"p3-b07-029","paper":3,"topic":"Cooling Tower","kind":"fact","front":"What drift loss do most end-user specifications call for, and what can modern PVC drift eliminators achieve?","back":"Most specifications call for 0.02% drift loss. Modern PVC drift eliminators can reach 0.003–0.001%.","explain":"Drift is water carried out of the tower as droplets in the air stream, separate from evaporation. Better eliminator shapes made from PVC made these lower values possible.","flash":false,"source":"BEE Book 3 Ch 07 p245","order":3371},
{"id":"p3-b07-030","paper":3,"topic":"Cooling Tower","kind":"fact","front":"What fan energy saving has been reported from replacing metal or GRP fan blades with hollow FRP blades, and what payback?","back":"Fan energy savings of about 20–30%, with a simple payback of 6 to 7 months.","explain":"Hand-moulded FRP blades can achieve an optimum aerodynamic profile. They are lightweight, need lower starting torque (so smaller motors), and extend gearbox, motor and bearing life.","flash":false,"source":"BEE Book 3 Ch 07 p245","order":3372},
{"id":"p3-b07-031","paper":3,"topic":"Cooling Tower","kind":"fact","front":"Rank cooling tower fan control methods from least to most effective.","back":"ON-OFF of single-speed fans (least effective), then two-speed fans, then three-speed fans, then automatic adjustable pitch or variable speed fans (closest control of cold water temperature).","explain":"In multi-cell towers, adjacent cells may run at different speeds, or some may be on while others are off, depending on load and the required water temperature.","flash":false,"source":"BEE Book 3 Ch 07 p247","order":3373},
{"id":"p3-b07-032","paper":3,"topic":"Cooling Tower","kind":"fact","front":"By how much may a 1°C rise in cooling water temperature increase the kW of an A/C compressor?","back":"About 2.7%.","explain":"The chapter also states that a 1°C drop in cooling water temperature can give a heat rate saving of about 5 kcal/kWh in a thermal power plant.","flash":false,"source":"BEE Book 3 Ch 07 p248","order":3374},
{"id":"p3-b07-033","paper":3,"topic":"Cooling Tower","kind":"fact","front":"Name five energy saving measures for cooling towers.","back":"Optimise fan blade angle seasonally or by load; correct excessive or uneven fan blade tip clearance; replace splash bars with PVC cellular film fill; replace slat drift eliminators with low pressure drop PVC cellular units; cover hot water basins to limit algae growth.","explain":"The chapter lists about twenty measures. Others include periodic cleaning of plugged nozzles, balancing flow to hot water basins, and optimising blow down to the COC limit.","flash":false,"source":"BEE Book 3 Ch 07 p248","order":3375},
{"id":"p3-b07-034","paper":3,"topic":"Cooling Tower","kind":"fact","front":"How is closed-loop VFD control of a cooling tower fan set up?","back":"An RTD sensor at the tower outlet sends a 4–20 mA signal to the drive's PID controller. The set point is entered in °C or °F, and the drive adjusts fan speed to remove any error.","explain":"If outlet temperature rises (from a higher wet bulb or plant load), the drive raises fan speed to bring it back to the set point. An optional bypass lets the fan run from mains supply if the drive fails.","flash":false,"source":"BEE Book 3 Ch 07 p249","order":3376},
{"id":"p3-b07-035","paper":3,"topic":"Cooling Tower","kind":"fact","front":"Why does a VFD save energy on a cooling tower fan that is rated for worst-case conditions?","back":"The fan is rated for the worst wet and dry bulb conditions, which occur for only a small part of the year. A VFD slows the fan in milder conditions, saving energy.","explain":"Savings need annual wet and dry bulb data, or a trial with and without the VFD. Savings are small in hot periods when the drive must run at full speed.","flash":false,"source":"BEE Book 3 Ch 07 p249","order":3377},
{"id":"p3-b07-036","paper":3,"topic":"Cooling Tower","kind":"problem","front":"A cooling tower cell circulates 1565 m³/hr from 44°C to 37.6°C at a 29.3°C wet bulb, and runs at 2.7 cycles of concentration. Find the range, approach, effectiveness, evaporation loss, blow down and make-up per cell.","back":"Range 6.4°C; approach 8.3°C; effectiveness 43.5% (rated 64.5%); evaporation 15.32 m³/hr; blow down 9.01 m³/hr; make-up 24.33 m³/hr per cell.","explain":"This is the chapter's trial on a thermal power plant cooling tower, which found the cell flow about 16.5% below rated. The same steps apply to any tower trial, using measured temperatures and the site COC.","flash":false,"source":"BEE Book 3 Ch 07 p247","steps":[{"prompt":"Calculate the range.","answer":"Range = 44 − 37.6 = 6.4°C.","explain":"Range is the inlet hot water temperature minus the outlet cold water temperature."},{"prompt":"Calculate the approach.","answer":"Approach = 37.6 − 29.3 = 8.3°C.","explain":"Approach is the outlet cold water temperature minus the ambient wet bulb temperature."},{"prompt":"Calculate the effectiveness.","answer":"Effectiveness = 6.4 / (6.4 + 8.3) × 100 = 43.5%. The rated value is 64.5%.","explain":"The rated value is 100 × (43 − 33) / (43 − 27.5), so the actual cell is well below its design effectiveness."},{"prompt":"Calculate the evaporation loss per cell.","answer":"0.00085 × 1.8 × 1565 × (44 − 37.6) = 15.32 m³/hr.","explain":"Evaporation depends on the circulation rate and the temperature drop across the tower."},{"prompt":"Calculate the blow down at 2.7 COC.","answer":"Blow down = 15.32 / (2.7 − 1) = 9.01 m³/hr.","explain":"Blow down removes concentrated water so that dissolved solids do not build up beyond the COC limit."},{"prompt":"Calculate the make-up water per cell.","answer":"Make-up = 15.32 + 9.01 = 24.33 m³/hr.","explain":"Make-up replaces water lost both to evaporation and to blow down."}],"order":3378},
{"id":"p3-b07-037","paper":3,"topic":"Cooling Tower","kind":"problem","front":"A tower's L/G ratio is found from a trial: water flow 1565 m³/hr, air flow 989,544 m³/hr at a density of 1.08 kg/m³. Find the L/G ratio and compare it with the design value.","back":"L/G = 1.46 kg/kg, against a rated value of 1.74 kg/kg.","explain":"A lower L/G than design means relatively more air for the water being cooled. The chapter links the lower flow per cell to a need to investigate the CW pump and system.","flash":false,"source":"BEE Book 3 Ch 07 p247","steps":[{"prompt":"Find the water mass flow rate.","answer":"1565 m³/hr × 1000 kg/m³ = 1,565,000 kg/hr.","explain":"Water density is taken as 1000 kg/m³ for mass flow."},{"prompt":"Find the air mass flow rate.","answer":"989,544 m³/hr × 1.08 kg/m³ = 1,068,708 kg/hr.","explain":"Air mass flow is volume flow multiplied by air density."},{"prompt":"Find the L/G ratio.","answer":"L/G = 1,565,000 / 1,068,708 = 1.46 kg/kg.","explain":"L/G is the ratio of water to air mass flow rates."},{"prompt":"Compare with design.","answer":"Rated L/G is 1.74 kg/kg, so the actual L/G is lower.","explain":"The book notes the flow per cell is about 16.5% below rated, which helps explain the lower L/G."}],"order":3379},
{"id":"p3-b07-038","paper":3,"topic":"Cooling Tower","kind":"problem","front":"A cooling tower handles 3000 m³/hr of water, with the hot water at 41°C, the cold water at 31°C and a wet bulb of 24°C. Find the range, approach, effectiveness and cooling capacity in kcal/hr.","back":"Range 10°C; approach 7°C; effectiveness 58.8%; cooling capacity 30 million kcal/hr.","explain":"This is the chapter's solved example. Cooling capacity is the mass flow times specific heat times temperature difference, which for water is kg/hr × 1 kcal/kg°C × range.","flash":false,"source":"BEE Book 3 Ch 07 p252","steps":[{"prompt":"Calculate the range.","answer":"Range = 41 − 31 = 10°C.","explain":"Range is hot water inlet minus cold water outlet temperature."},{"prompt":"Calculate the approach.","answer":"Approach = 31 − 24 = 7°C.","explain":"Approach is cold water outlet minus the wet bulb temperature."},{"prompt":"Calculate the effectiveness.","answer":"Effectiveness = 10 / (10 + 7) × 100 = 58.8%.","explain":"Effectiveness is range divided by the ideal range (range plus approach)."},{"prompt":"Calculate the cooling capacity.","answer":"Capacity = 3000 × 1000 × (41 − 31) = 30,000,000 kcal/hr = 30 million kcal/hr.","explain":"Flow in m³/hr is converted to kg/hr (×1000), then multiplied by the temperature drop, since water's specific heat is 1 kcal/kg°C."}],"order":3380},
{"id":"p3-b07-039","paper":3,"topic":"Cooling Tower","kind":"problem","front":"A cooling tower fan's manual control uses 392 kWh/day and VFD control uses 254 kWh/day. The fan runs 26 days a month for 12 months, and the drive panel costs Rs 2,50,000. Find the daily saving, the percentage saving, the annual saving and the payback period.","back":"Daily saving 138 kWh (35.2%); annual saving Rs 2,15,280; payback about 1.16 years.","explain":"The chapter's figures are extrapolated annual estimates. In hot periods the VFD runs at full speed, so the real average annual saving is lower.","flash":false,"source":"BEE Book 3 Ch 07 p251","steps":[{"prompt":"Find the daily energy saving.","answer":"392 − 254 = 138 kWh/day.","explain":"Saving is the manual control consumption minus the VFD consumption."},{"prompt":"Find the percentage saving.","answer":"138 / 392 × 100 = 35.2%.","explain":"Percentage saving is the daily saving divided by the manual control consumption."},{"prompt":"Find the annual energy saving.","answer":"138 × 26 × 12 = 43,056 kWh/yr.","explain":"Multiply the daily saving by the operating days per month and by 12 months."},{"prompt":"Find the implied unit energy cost and check the annual money saving.","answer":"The chapter states Rs 2,15,280 per year. This implies about Rs 5 per kWh (215,280 / 43,056). The unit cost line is not legible in the OCR, so the Rs 5 figure is derived, not quoted.","explain":"Annual money saving is annual kWh saved multiplied by the unit energy cost."},{"prompt":"Find the simple payback.","answer":"Payback = 2,50,000 / 2,15,280 = 1.16 years.","explain":"Simple payback is the capital cost divided by the annual saving."}],"order":3381},
{"id":"p3-b07-040","paper":3,"topic":"Cooling Tower","kind":"problem","front":"A cooling tower circulates 1250 m³/hr with a range of 7°C. Blow down is 1% of the circulation rate. Estimate the evaporation loss and the cycles of concentration.","back":"Evaporation about 13.4 m³/hr; blow down 12.5 m³/hr; COC about 2.07.","explain":"Blow down is found from the circulation rate, then COC is found by rearranging the blow down formula. Evaporation loss uses the empirical 0.00085 × 1.8 relation from the chapter.","flash":false,"source":"BEE Book 3 Ch 07 p254","steps":[{"prompt":"Calculate the evaporation loss.","answer":"0.00085 × 1.8 × 1250 × 7 = 13.39 m³/hr.","explain":"The range of 7°C is used as the temperature difference T1 − T2."},{"prompt":"Calculate the blow down.","answer":"Blow down = 1% × 1250 = 12.5 m³/hr.","explain":"Blow down is given as a percentage of the circulation rate."},{"prompt":"Calculate the COC.","answer":"COC − 1 = Evaporation / Blow down = 13.39 / 12.5 = 1.07, so COC ≈ 2.07.","explain":"Rearranging blow down = evaporation / (COC − 1) gives COC = 1 + evaporation / blow down."}],"order":3382},
{"id":"p3-b07-041","paper":3,"topic":"Cooling Tower","kind":"fact","front":"True or false: range is a better indicator of cooling tower performance than approach.","back":"False. Approach is the better indicator. Range is set mainly by the process heat load.","explain":"Both should be monitored, but approach shows how closely the tower brings cold water to the ambient wet bulb. The chapter's objective question uses this same distinction.","flash":true,"source":"BEE Book 3 Ch 07 p236","order":3383},
{"id":"p3-b08-001","paper":3,"topic":"Lighting Basics","kind":"fact","front":"How many lumens is 1 watt equal to at 555 nm, the wavelength the eye sees best?","back":"683 lumens (683 lm/W). The lumen is the photometric equivalent of the watt, weighted to the standard observer's eye response.","explain":"Yellowish-green light at 555 nm gives the most visual response per watt. Blue or red light of the same radiant power looks dimmer to the eye. This is why 683 lm/W is the ceiling for luminous efficacy.","flash":true,"source":"BEE Book 3 Ch 08 p257","order":3384},
{"id":"p3-b08-002","paper":3,"topic":"Lighting Basics","kind":"fact","front":"What is illuminance, and what is its unit?","back":"Illuminance is the luminous flux incident on a surface per unit area. Its unit is the lux (lx), where 1 lux = 1 lumen per square metre.","explain":"Illuminance is measured on the working plane, the main plane where tasks are carried out. It affects both task performance and how the space looks. Average maintained illuminance is the average of readings taken across an area.","flash":false,"source":"BEE Book 3 Ch 08 p258","order":3385},
{"id":"p3-b08-003","paper":3,"topic":"Lighting Basics","kind":"fact","front":"State the inverse square law for illuminance from a point source.","back":"E = I / d², where E is illuminance (lx), I is luminous flux (lm) and d is distance (m). Illuminance falls with the square of distance. The alternate form is E₁ × d₁² = E₂ × d₂².","explain":"Doubling the distance cuts illuminance to one quarter. Distance is measured from the test point to the first luminating surface, such as the filament of a clear bulb or the glass envelope of a frosted bulb.","flash":false,"source":"BEE Book 3 Ch 08 p259","order":3386},
{"id":"p3-b08-004","paper":3,"topic":"Lighting Basics","kind":"fact","front":"What is lamp circuit efficacy, and how does it differ from lamp efficacy?","back":"Lamp circuit efficacy is the lumens emitted per circuit watt, which includes control gear losses. It is the more meaningful measure for lamps that need control gear.","explain":"Lamp efficacy counts only the lamp's own watts. Circuit efficacy also counts the ballast losses, so it gives the true energy cost of the light. Its unit is lumens per circuit watt (lm/W).","flash":false,"source":"BEE Book 3 Ch 08 p259","order":3387},
{"id":"p3-b08-005","paper":3,"topic":"Lighting Basics","kind":"fact","front":"What does the Colour Rendering Index (CRI) measure, and what does a CRI of 100 mean?","back":"CRI measures the effect of a lamp's light on the perceived colour of standard colour chips, compared with a reference source of the same correlated colour temperature. A CRI of 100 means the chips look identical under the lamp and the reference. A low CRI means some colours look unnatural.","explain":"CRI is found by measuring the colour appearance of the chips under the lamp and under the reference. Any difference from the reference pulls the CRI below 100. Lamps with low CRI are poor for colour-critical work.","flash":true,"source":"BEE Book 3 Ch 08 p260","order":3388},
{"id":"p3-b08-006","paper":3,"topic":"Control Gear","kind":"fact","front":"What is the function of a ballast in a fluorescent lamp circuit?","back":"A ballast is a current-limiting device that counters the negative resistance of a discharge lamp. It aids the initial voltage build-up needed to start the lamp and acts as a stabiliser in the circuit.","explain":"A fluorescent tube cannot run from the mains directly. The ballast is the auxiliary circuit housed in a casing that provides the start-up and steady operation. Ignitors do a similar starting job for HID lamps by sending a high-voltage pulse.","flash":false,"source":"BEE Book 3 Ch 08 p260","order":3389},
{"id":"p3-b08-007","paper":3,"topic":"Lamp Types","kind":"fact","front":"Into which three groups are lamps classified by construction and operating characteristics?","back":"Incandescent, fluorescent and high intensity discharge (HID). HID lamps are further classified as sodium vapour, mercury vapour and metal halide.","explain":"The group determines efficacy, colour, lamp life and how much light the lamp loses over its life. Knowing the three groups makes the individual lamp types easier to place.","flash":false,"source":"BEE Book 3 Ch 08 p260","order":3390},
{"id":"p3-b08-008","paper":3,"topic":"Lamp Types","kind":"fact","front":"How does the halogen cycle stop the filament of a halogen lamp from thinning?","back":"Tungsten evaporates from the hot filament and combines with halogen at the cooler bulb wall to form tungsten oxyhalide. This vapour drifts back to the hot filament, where it breaks apart and tungsten is re-deposited on the filament.","explain":"The re-deposited tungsten does not return to the exact spot it left. Breaks still tend to occur near the lead-in connections, where temperature drops sharply. Halogen lamps are more efficient and last longer than standard incandescent lamps.","flash":false,"source":"BEE Book 3 Ch 08 p261","order":3391},
{"id":"p3-b08-009","paper":3,"topic":"Lamp Types","kind":"fact","front":"How much more efficient and how much longer-lived is a fluorescent tube lamp than a standard incandescent lamp?","back":"About 3 to 5 times as efficient, and it can last about 10 to 20 times longer.","explain":"These are the general comparison figures given in the chapter. Fluorescent lamps need a ballast and a starter circuit, and their luminous flux depends strongly on ambient temperature.","flash":false,"source":"BEE Book 3 Ch 08 p262","order":3392},
{"id":"p3-b08-010","paper":3,"topic":"Lamp Types","kind":"fact","front":"What diameters do the T12, T8 and T5 linear fluorescent tubes have?","back":"T12 = 38 mm (1.5 in), T8 = 25 mm (1 in) and T5 = 16 mm (5/8 in). The T number is the diameter in eighths of an inch.","explain":"T5 and T8 are the thinner tubes. The chapter says T5 and T8 give about 5% higher efficacy than 40 W T12 lamps and have become the most popular choice for new installations.","flash":false,"source":"BEE Book 3 Ch 08 p262","order":3393},
{"id":"p3-b08-011","paper":3,"topic":"Lamp Types","kind":"fact","front":"Why is low pressure sodium (LPSV) a poor choice where colour matters?","back":"LPSV is monochromatic, so all colours appear black, white or shades of grey under it. It is used for outdoor security and street lighting and for low-wattage indoor areas such as stairwells.","explain":"LPSV is the most efficacious light source of all the lamp types, but it gives the poorest quality of light. Many municipalities do not allow it for roadway lighting because the colour rendition is so poor.","flash":true,"source":"BEE Book 3 Ch 08 p263","order":3394},
{"id":"p3-b08-012","paper":3,"topic":"Lamp Types","kind":"fact","front":"What does a metal halide lamp add to a high pressure mercury vapour lamp, and why does it render colour better?","back":"It adds metal halides, usually rare-earth iodides or a mixture of sodium and scandium iodide, so that metal radiation augments the mercury spectrum. Its colour rendering is significantly better than mercury vapour and can be tailored by the choice of halides.","explain":"The halides act like the tungsten halogen cycle. At high temperature the halide compound dissociates and releases the metal into the arc. The halides also stop the quartz wall being attacked by alkali metals.","flash":false,"source":"BEE Book 3 Ch 08 p264","order":3395},
{"id":"p3-b08-013","paper":3,"topic":"Lamp Types","kind":"fact","front":"How does an LED produce light?","back":"By electroluminescence. Current drives electrons from N-type material (extra electrons) into holes in P-type material (extra positive gaps). When an electron drops into a hole it releases its extra energy as light.","explain":"The LED chip is usually less than one square millimetre, and additional optical components shape and direct the light. Different inorganic semiconductor materials produce different colours.","flash":false,"source":"BEE Book 3 Ch 08 p265","order":3396},
{"id":"p3-b08-014","paper":3,"topic":"Lamp Types","kind":"fact","front":"True or false: LEDs are inherently white light sources.","back":"False. LEDs emit nearly monochromatic light, so white light has to be produced by phosphor conversion, RGB colour mixing or a hybrid method.","explain":"That is why coloured LEDs are used directly in traffic lights and exit signs. A general-purpose white LED needs a conversion or mixing method to make white light.","flash":true,"source":"BEE Book 3 Ch 08 p266","order":3397},
{"id":"p3-b08-015","paper":3,"topic":"Lamp Types","kind":"fact","front":"What are the three ways to produce white light from LEDs?","back":"Phosphor conversion (a blue or UV LED with a phosphor), RGB colour mixing of red, green and blue LEDs, and a hybrid method that combines phosphor-converted and monochromatic LEDs.","explain":"In a phosphor-converted LED, the phosphor on or near the LED turns the blue or near-UV light into white light. In RGB mixing, the proper amounts of the three colours combine to give white.","flash":false,"source":"BEE Book 3 Ch 08 p266","order":3398},
{"id":"p3-b08-016","paper":3,"topic":"Lamp Types","kind":"fact","front":"What efficacy do LEDs reach in the laboratory and in typical products?","back":"Up to 200 lumens per watt in the laboratory and in some products on the market. More typical LEDs average 50 to 130 lumens per watt.","explain":"Low power requirements make solar panels with battery backup practical and economical for remote LED applications. LEDs direct their light instead of radiating it in all 360 degrees.","flash":false,"source":"BEE Book 3 Ch 08 p266","order":3399},
{"id":"p3-b08-017","paper":3,"topic":"Illuminance Levels","kind":"fact","front":"What is the recommended scale of illuminances in lux?","back":"20-30-50-75-100-150-200-300-500-750-1000-1500-2000 lux. Each step is about 1.5 times the one before.","explain":"A factor of about 1.5 represents the smallest significant difference in the subjective effect of illuminance. Each recommended range spans three successive steps of this scale, with R as the middle value.","flash":false,"source":"BEE Book 3 Ch 08 p269","order":3400},
{"id":"p3-b08-018","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"When is the Zonal Cavity Method used, and why is it preferred?","back":"It is the accepted method for average illuminance indoors, unless the light distribution is radically asymmetric. It is an accurate hand method because it accounts for the effect of inter-reflectance on illuminance.","explain":"For outdoor lighting the chapter uses a different route: the coefficient of utilisation is read from a curve and the standard lumen formula is applied.","flash":false,"source":"BEE Book 3 Ch 08 p270","order":3401},
{"id":"p3-b08-019","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"What are the three cavities in the Zonal Cavity Method?","back":"The ceiling cavity (between ceiling and fixtures), the room cavity (between fixtures and work plane) and the floor cavity (between work plane and floor).","explain":"The method treats the room as three stacked spaces. The room cavity is the space the luminaires light, and its height is what the room index uses.","flash":true,"source":"BEE Book 3 Ch 08 p271","order":3402},
{"id":"p3-b08-020","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"What is the room index formula used in the Zonal Cavity Method?","back":"Room index = (L × W) / [mounting height × (L + W)], where mounting height = luminaire height minus work plane height.","explain":"In the chapter's example a 10 m × 10 m room with a 2.0 m mounting height gives RI = 100 / (2 × 20) = 2.5. The room index is then used to read the utilisation factor from the manufacturer's table.","flash":true,"source":"BEE Book 3 Ch 08 p272","order":3403},
{"id":"p3-b08-021","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"Define utilisation factor (UF) and state where its value comes from.","back":"UF is the percent of rated bare-lamp lumens that leave the luminaire and reach the work plane, counting both direct and reflected light. Manufacturers supply a CU or UF table for each luminaire from a photometric test report.","explain":"UF depends on the luminaire type, the room index, and the ceiling and wall reflectances. For a twin tube fixture at room index 2.5, the chapter gives UF = 0.66.","flash":false,"source":"BEE Book 3 Ch 08 p272","order":3404},
{"id":"p3-b08-022","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"What is the lumen-method formula for the number of luminaires required?","back":"N = (E × A) / (F × UF × LLF). E is the required lux on the working plane, A is the room area (L × W), F is the total lumens from all lamps in one fitting, UF is the utilisation factor and LLF is the light loss factor.","explain":"Use the room area in m² and the required lux, so that the units cancel to give a count of fittings. Round the result to whole fittings as the design requires.","flash":false,"source":"BEE Book 3 Ch 08 p272","order":3405},
{"id":"p3-b08-023","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"What does the light loss factor (LLF) cover, and what are the typical values for an air-conditioned office, a clean industrial site and a dirty industrial site?","back":"LLF covers the depreciation of lamp output over time and dirt on fittings and walls. LLF = lamp lumen MF × luminaire MF × room surface MF. Typical values are 0.8 (air-conditioned office), 0.7 (clean industrial) and 0.6 (dirty industrial).","explain":"MF is the maintenance factor. A lower LLF means more light is lost, so more fittings are needed for the same lux level.","flash":false,"source":"BEE Book 3 Ch 08 p273","order":3406},
{"id":"p3-b08-024","paper":3,"topic":"Illuminance Calculation","kind":"fact","front":"What is the space-to-height ratio (SHR) of a luminaire, and what is the recommended value for the example fitting?","back":"SHR = spacing between luminaires / mounting height. The recommended value for the example luminaire is 1.5. A larger SHR means fewer fittings and a lower connected load.","explain":"If the actual SHR is more than the recommended value, the uniformity of lighting becomes less. Luminaires closer to a wall should be spaced at half the spacing or less.","flash":false,"source":"BEE Book 3 Ch 08 p273","order":3407},
{"id":"p3-b08-025","paper":3,"topic":"Energy Saving Options","kind":"fact","front":"Name four daylighting methods the chapter gives for using natural light in buildings.","back":"North lighting by single-pitched saw-tooth trusses; skylights with FRP material and a transparent or translucent false ceiling; light shelves at windows; and solar tubes on the roof that direct sunlight deep into the building.","explain":"North lighting suits latitudes north of 23 degrees, such as North India. In South India it needs diffusing glass to cut out direct sunlight. Atriums with FRP domes can remove the need for electric lights in tall-building passages.","flash":false,"source":"BEE Book 3 Ch 08 p274","order":3408},
{"id":"p3-b08-026","paper":3,"topic":"Energy Saving Options","kind":"fact","front":"What is de-lamping, and under what conditions does it work?","back":"De-lamping means removing lamps to reduce lighting energy. It works when the mounting height is reduced and efficient luminaires are fitted, so the illuminance is hardly affected. It also suits empty spaces where no active work is done.","explain":"De-lamping sits alongside task lighting and daylighting as a way to cut lighting energy without changing the lamps themselves.","flash":false,"source":"BEE Book 3 Ch 08 p275","order":3409}
]$cards$::jsonb);
